def lps(str):
    """Write a function to find the longest palindromic subsequence in the given string."""
    n = len(str)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if str[i] == str[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                left = dp[i + 1][j]
                right = dp[i][j - 1]
                dp[i][j] = left if left > right else right
    return dp[0][n - 1]
